commands.cmd:
cat > infra/rules.guard <<'EOF'
let sgs = Resources.*[ Type == "AWS::EC2::SecurityGroup" ]
rule no_ssh_from_internet when %sgs !empty {
  %sgs.Properties.SecurityGroupIngress[*] { when FromPort == 22 { CidrIp != "0.0.0.0/0" } }
}
let vols = Resources.*[ Type == "AWS::EC2::Volume" ]
rule volumes_encrypted when %vols !empty {
  %vols.Properties.Encrypted == true
}
EOF
curl --proto "=https" --tlsv1.2 -sSf https://raw.githubusercontent.com/aws-cloudformation/cloudformation-guard/main/install-guard.sh | sh >/dev/null 2>&1; ~/.guard/bin/cfn-guard validate --data infra/template.yaml --rules infra/rules.guard --show-summary pass,fail 2>&1 | tail -3
